<title>Mount Fuji &amp; Chureito Pagoda at Dusk</title>
<meta name="viewport" content="width=device-width, initial-scale=1">
<style>
  html, body { margin: 0; height: 100%; overflow: hidden; background: #241a3e; }
  canvas { display: block; }
</style>
