<script type="module">
import * as THREE from 'three';

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.12;
document.body.appendChild(renderer.domElement);

const scene = new THREE.Scene();
scene.fog = new THREE.FogExp2(0xe89a72, 0.0038);

const camera = new THREE.PerspectiveCamera(50, window.innerWidth / window.innerHeight, 0.1, 1200);
const CAM_BASE = new THREE.Vector3(17, 7, 32);
const CAM_TARGET = new THREE.Vector3(-3, 7.5, -46);
camera.position.copy(CAM_BASE);
camera.lookAt(CAM_TARGET);

// ---------- lighting: warm dusk sun ----------
const SUN_DIR = new THREE.Vector3(26, 20, -150).normalize();
const sun = new THREE.DirectionalLight(0xffb27a, 2.0);
sun.position.copy(SUN_DIR).multiplyScalar(200);
scene.add(sun);
scene.add(new THREE.HemisphereLight(0xffd9c4, 0x332a52, 0.85));
const fill = new THREE.DirectionalLight(0xc9a8e8, 0.75);
fill.position.set(30, 35, 110);
scene.add(fill);

// ---------- sky dome (procedural dusk gradient + sun glow) ----------
const sky = new THREE.Mesh(
  new THREE.SphereGeometry(600, 32, 16),
  new THREE.ShaderMaterial({
    side: THREE.BackSide,
    depthWrite: false,
    fog: false,
    uniforms: { uSun: { value: SUN_DIR.clone() } },
    vertexShader: `
      varying vec3 vDir;
      void main() {
        vDir = position;
        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
      }`,
    fragmentShader: `
      varying vec3 vDir;
      uniform vec3 uSun;
      void main() {
        vec3 d = normalize(vDir);
        float h = clamp(d.y * 0.5 + 0.5, 0.0, 1.0);
        vec3 low  = vec3(0.99, 0.72, 0.50);
        vec3 mid  = vec3(0.90, 0.47, 0.42);
        vec3 top  = vec3(0.15, 0.12, 0.34);
        vec3 col = mix(low, mid, smoothstep(0.44, 0.56, h));
        col = mix(col, top, smoothstep(0.56, 0.92, h));
        float s = max(dot(d, normalize(uSun)), 0.0);
        col += vec3(1.0, 0.78, 0.52) * pow(s, 350.0) * 1.4;
        col += vec3(1.0, 0.58, 0.34) * pow(s, 7.0) * 0.28;
        gl_FragColor = vec4(col, 1.0);
      }`
  })
);
scene.add(sky);

// ---------- ground ----------
const groundGeo = new THREE.PlaneGeometry(800, 800, 56, 56);
groundGeo.rotateX(-Math.PI / 2);
