  for (let i = 0; i < p.count; i++) {
    const x = p.getX(i), z = p.getZ(i);
    const d = Math.hypot(x, z);
    const k = Math.min(1, d / 40);
    p.setY(i, (Math.sin(x * 0.11) * Math.cos(z * 0.09) + Math.sin(x * 0.31 + z * 0.21)) * 0.55 * k);
  }
